brokenCode.code:
console.log('start');
setTimeout(function () {
  console.log('data loaded');
}, 0);
console.log('done');
// expected: start, data loaded, done
// actual:   start, done, data loaded

solution.code:
console.log('start');
setTimeout(function () {
  console.log('data loaded');
  console.log('done'); // put dependent work inside the callback
}, 0);
// order: start, data loaded, done

console.log('A');
setTimeout(() => console.log('B'), 0);
console.log('C');
// Output order: A, C, B
